                // deprecation repair on every call.
                expect(calls).toEqual([
                    {
                        data: { config_entry_id: 'entry-1', credential_type: 'pin', length: 4 },
                        domain: 'lock_code_manager',
                        service: 'generate_credential'
                    }
                ]);
